<?php require_once __DIR__.'/../includes/requireLogin.php';require_once __DIR__.'/../includes/authorization.php';require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';require_once __DIR__.'/../services/authService.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}requireLogin();requireRole('admin');requireValidCsrf();$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$p=openDatabase();if(!$id||!findUserById($p,$id)){http_response_code(404);exit('Account not found');}try{if($action==='role'){$role=(string)($_POST['role']??'');if(!in_array($role,['student','tutor','admin'],true))throw new InvalidArgumentException('Invalid role.');if($id===(int)$_SESSION['user_id']&&!in_array('admin',loadRoles($p,$id),true))throw new InvalidArgumentException('You cannot remove your own administrator role.');replaceUserRole($p,$id,$role);}elseif($action==='status'){$active=(string)($_POST['active']??'');if(!in_array($active,['0','1'],true))throw new InvalidArgumentException('Invalid status.');$roles=loadRoles($p,$id);if($active==='0'&&in_array('admin',$roles,true)&&activeAdminCount($p)<=1)throw new InvalidArgumentException('The last active administrator cannot be deactivated.');setUserActive($p,$id,$active==='1');}elseif($action==='delete'){[$allowed,$reason]=deleteAllowed($p,$id);if(!$allowed)throw new InvalidArgumentException($reason);deleteUserWithoutRequests($p,$id);header('Location: manage-users.php?updated=1',true,303);exit;}else throw new InvalidArgumentException('Invalid action.');header('Location: manage-user.php?user_id='.$id,true,303);exit;}catch(InvalidArgumentException $e){http_response_code(422);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Account was not updated</h1><div class="alert alert-danger"><?=htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8')?></div><a href="manage-user.php?user_id=<?=$id?>">Return to account</a></main><?php require __DIR__.'/../includes/footer.php';}
